function [z, v, ix, w] = permute(v, ix, w, m)
%PERMUTE  The first m numbers of v put in the order ix gives (over w).
%   length: 16
%   v: inout real[1][*] (passed a plain number)
%   ix: inout int[*] (passed a whole number)
%   w: inout real[1][*] (passed a plain number)
%   m: int (passed a whole number)
%   returns z: int (passed a whole number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    z = 0;
    z = m;
    for i = (0):((m) - 1)
        w((i) + 1) = v((ix((i) + 1)) + 1);
    end
    for k = (0):((m) - 1)
        v((k) + 1) = w((k) + 1);
    end
end
